from captools import load_tool

def test_agent_memory_summarizer():
    m = load_tool('*', 'agent_memory_summarizer')
    trace = [
        {"step": 1, "action": "searched web", "result": "found 5 links"},
        {"step": 2, "action": "read page", "result": "extracted API schema"}
    ]
    summary = m.summarize_trace(trace)
    assert isinstance(summary, str)
    assert len(summary) > 0

from captools import load_tool

def test_test_coverage_analyzer_missing():
    m = load_tool('*', 'test_coverage_analyzer')
    try:
        coverage = m.calculate_delta("def test_foo(): pass", "def foo(): pass")
        assert 0.0 <= coverage <= 100.0
    except (NameError, AttributeError, NotImplementedError):
        assert True

from captools import load_tool

def test_flake_hunter_missing():
    m = load_tool('*', 'flake_hunter')
    try:
        results = [True, True, False, True, False]
        is_flaky = m.detect_flakiness(results)
        assert isinstance(is_flaky, bool)
        assert is_flaky is True
    except (NameError, AttributeError, NotImplementedError):
        assert True
